;       lcd_cmd(0x11);   delay_ms(120);      // Sleep Out @ 0x08026982
;       lcd_cmd(0xB2); lcd_dat5(0x05,0x05,0x00,0x33,0x33); // Porch @ 0x0802698E
;       lcd_cmd(0xB7); lcd_dat(0x35);        // Gate ctrl  @ 0x080269B2
;       lcd_cmd(0xC0); lcd_dat(0x2C);        // LCM ctrl   @ 0x080269BE
;       lcd_cmd(0xC2); lcd_dat(0x01);        // VDV/VRH en @ 0x080269CA
;       lcd_cmd(0xC3); lcd_dat(0x0F);        // VRH set    @ 0x080269D6
;       lcd_cmd(0xC4); lcd_dat(0x20);        // VDV set    @ 0x080269E2
;       lcd_cmd(0xC6); lcd_dat(0x11);        // Frame rate  @ 0x080269EE
;       lcd_cmd(0xD0); lcd_dat2(0xA4,0xA1);  // Power ctrl @ 0x080269FA
;       lcd_cmd(0xE8); lcd_dat(0x03);        // EQ time    @ 0x08026A0C
;       lcd_cmd(0xE9); lcd_dat3(0x09,0x09,0x08); // Gate time @ 0x08026A18
;       lcd_cmd(0xBB); lcd_dat(0x3F);        // VCOM       @ 0x08026A30
;       lcd_cmd(0xE0); /* +gamma 14 params */ // @ 0x08026A3C
;       lcd_cmd(0xE1); /* -gamma 14 params */ // @ 0x08026A96
;       lcd_cmd(0x36); lcd_dat(0xC0);        // MADCTL 180 @ 0x08026AF0
