; --- 10. ADC2 battery/audio read - adc2_convert_read @ 0x080227AC -----------
;
;   /* OEM ADC2 initialization and read functions.
;    * ADC2 base = 0x40012800.  APB2 prescaler /6 → 10 MHz ADC clock.
;    * Two channels: PA0 (ch0, battery), PA1 (ch1, audio/VOX).
;    * Sample time = 239.5 cycles (SMP=7), single-shot SW trigger.
;    * Results: 12-bit → UBFX(DR,4,8) → 8-bit. */
;
;   void adc2_init(void) {                    // @ 0x080227AC
;       CRM_CFGR |= 0x8000;                  // ADCPRE /6 @ 0x080227B0
;       CRM_APB2EN |= 0x0600;                // ADC1+ADC2 clock @ 0x080227BA
;       ADC2 = 0x40012800;                    // literal @ 0x080227E2
;       ADC2->CR2 |= ADON;                   // power on @ 0x080227E8
;       ADC2->CR2 |= RSTCAL; wait(!RSTCAL);  // reset cal @ 0x08022800
;       ADC2->CR2 |= CAL;    wait(!CAL);     // calibrate @ 0x08022810
;   }
;
;   uint8_t adc_read_pa0_battery(void) {      // @ 0x0801385C
;       adc_set_channel(ADC2, ch=0, seq=1, smp=7);  // @ 0x08013860
;       ADC2->CR2 |= SWSTART;                // trigger @ 0x08013878
;       while (!(ADC2->SR & EOC));            // poll @ 0x0801387C
;       ADC2->SR = 0;                         // clear flags
;       uint16_t dr = ADC2->DR & 0x0FFF;     // 12-bit result
;       return ubfx(dr, 4, 8);               // bits [11:4] @ 0x08013892
;   }
;
;   uint8_t adc_read_pa1_audio(void) {        // @ 0x08013820
;       adc_set_channel(ADC2, ch=1, seq=1, smp=7);  // @ 0x08013826
;       // ... same SWSTART/poll/UBFX pattern
;       return ubfx(dr, 4, 8);               // @ 0x08013852
;   }
;

; --- 11. BK4829 SPI write/read - Chip0_Write @ 0x0801C090 -------------------
;
;   /* OEM BK4829 SPI bit-bang protocol.
;    * 3-wire: PE8/PE15=SEN (CS), PE10=SCK, PE11=SDA (bidirectional).
;    * 24-bit frame: [0x80|reg_addr(7b)] [data_hi(8b)] [data_lo(8b)].
;    * MSB-first, CPOL=0, CPHA=0 (data setup before rising clock edge). */
;
;   void bk4829_chip0_write(uint8_t reg, uint16_t val) {  // @ 0x0801C090
;       uint32_t frame = (0x80 | reg) << 16 | val;
;       gpio_clear(GPIOE, PIN_8);   // SEN1 LOW (select chip 0)
;       for (int i = 23; i >= 0; i--) {
;           gpio_clear(GPIOE, PIN_10);     // SCK LOW
;           if (frame & (1 << i))
;               gpio_set(GPIOE, PIN_11);   // SDA HIGH
;           else
;               gpio_clear(GPIOE, PIN_11); // SDA LOW
;           delay_250ns();                 // OEM loop @ 0x0800A962
;           gpio_set(GPIOE, PIN_10);       // SCK HIGH (latch)
;           delay_250ns();
;       }
;       gpio_clear(GPIOE, PIN_10);         // SCK LOW (idle)
;       gpio_set(GPIOE, PIN_8);            // SEN1 HIGH (deselect)
;   }
;
;   uint16_t bk4829_chip0_read(uint8_t reg) {    // @ 0x0801BFC4
;       uint8_t cmd = 0x80 | reg;
;       gpio_clear(GPIOE, PIN_8);          // SEN1 LOW
;       shift_out(cmd, 8);                 // send address byte
;       config_sda_input();                // SDA → floating input
;       uint16_t val = shift_in(16);       // read 16 data bits
;       config_sda_output();               // SDA → push-pull output
;       gpio_set(GPIOE, PIN_8);            // SEN1 HIGH
;       return val;
;   }
;
;   // Chip 1 uses same protocol, PE15 for SEN2:
;   // bk4829_chip1_write @ 0x0801C0E4
;   // bk4829_chip1_read  @ 0x0801B908
;

; --- 12. BK4829 mode switch - peripheral_bus_select @ 0x0801B9CC -----------
;
;   /* REG_30 mode values (verified at 0x0801BA1A-0x0801BA3C):
;    *   RX    = 0xBFF1,  TX    = 0xC1FE,
;    *   AM_RX = 0x0302,  SCAN  = 0xC3FA
;    *
;    * REG_47 AGC table at 0x0802B80C: [0xDB27, 0xBB94, 0x6616, 0xEB4F]
;    * REG_47 base = 0x6042, final = base | lut[mode] @ 0x0801BC30
;    *
;    * REG_48 gain = 0xB00F | (cal_value << 4) @ 0x0801BC50
;    * REG_48 AM   = 0xB0A3 (fixed) */
;

; --- 13. Audio path - beep_play @ 0x08003808, spk_mute @ 0x08019254 ---------
;
;   /* OEM audio routing for beep playback:
;    *   1. SET PC12 (BEEP_SW)  - route beep to speaker    @ 0x080038EA
;    *   2. SET PB8  (AMP_EN)   - enable audio amplifier   @ 0x08006574
;    *   3. Configure TIM6: PSC=3, ARR=781 (~38.4 kHz sample rate)
;    *   4. DMA2_CH3 → DAC_DHR12R1 (0x40007408), circular, 16 halfwords
;    *   5. Enable DAC + TIM6 → tone plays
;    *   6. After duration: stop TIM6, CLR PB8, CLR PC12
;    *
;    * TX speaker mute:
;    *   spk_mute_on_ptt @ 0x08019254: SET PE1 + SET PB8 (mute+mic)
;    *   spk_unmute      @ 0x0801929C: CLR PE1 + CLR PB8 (unmute+mic off)
;    *   PE1 polarity: HIGH = speaker muted */
;
; --- 14. Radio relay_select - rf_relay_switch @ 0x0801D268 ------------------
;
;   /* OEM relay control - 6 GPIOs, all ACTIVE-LOW, 4 modes.
;    * relay_select(sub_mode, mode) @ 0x0801D268 (378 bytes)
;    *
;    * Mode 0 (@ 0x0801D290) - Full TX assert:
;    *   CLR PE13, CLR PE7, CLR PB1, CLR PE12, CLR PB0, CLR PE14
;    *   (all 6 relay pins driven LOW - no delays between writes)
;    *
;    * Mode 1 (@ 0x0801D2C4) - RX band/path selection:
;    *   sub_mode=0 (VHF):  CLR PE13, CLR PE12, SET PB0
;    *   sub_mode=1,2,3:    CLR PE13, CLR PB0, CLR PE12
;    *   sub_mode=4 (spec): CLR PE12, CLR PB0, SET PE13
;    *   All: SET PE7, SET PB1, SET PE14 (audio group deasserted)
;    *
;    * Mode 2 (@ 0x0801D338) - Audio path selection:
;    *   sub_mode=0,2 (VHF/1.25m): CLR PB1, SET PE7, CLR PE14
;    *   sub_mode=1,3 (UHF/300):   CLR PE7, SET PB1, CLR PE14
;    *   sub_mode=4:               CLR PE7, CLR PB1, SET PE14 (PA off)
;    *
;    * Mode 3 (@ 0x0801D3C6) - Antenna path (fixed):
;    *   CLR PE13, CLR PE12, CLR PB0
;    *
;    * TX sequence (@ 0x0801A5D0):
;    *   1. relay_select(sub, 0) - assert all
;    *   2. bk4829_set_mode(TX, REG_30=0xC1FE)
;    *   3. relay_select(sub, 2) - audio path
;    *
;    * TX-off sequence (@ 0x0801C308):
;    *   1. relay_select(sub, 1) - RX band/path
;    *   2. bk4829_set_mode(RX, REG_30=0xBFF1)
;    *
;    * RF frontend (@ 0x08022E3C):
;    *   PB8+PE4 always SET/CLR together as paired enable.
;    *   Not band-select; filter config is BK4829 registers. */
;
; --- 15. VFO frequency + band validation ------------------------------------
;
;   /* RX band limits enforced in vfo_load_state() and vfo_set_frequency():
;    *   Band 0: 136–174 MHz (2m VHF)   → submode 0
;    *   Band 1: 220–260 MHz (1.25m)    → submode 2
;    *   Band 2: 300–390 MHz (disabled) → submode 3
;    *   Band 3: 400–520 MHz (70cm UHF) → submode 1
;    *
;    * Valid step sizes (Hz): 2500, 5000, 6250, 10000, 12500,
;    *                        15000, 20000, 25000, 30000, 50000
;    *
;    * vfo_step() wraps at band edges (top→bottom, bottom→top).
;    * TX validation via calibration_tx_allowed() - separate from RX bands. */
;
; --- 16. GPS module - USART3 + PA8 power control ---------------------------
;
;   /* GPS power control (PA8):
;    *   gpio_modes_init @ 0x0801391C: configures PA8 as GPIO output
;    *   GPS enable:  SET PA8 @ 0x080095A6 (gpio_bits_set GPIOA 0x100)
;    *   GPS disable: CLR PA8 @ 0x08013FE0 (gpio_bits_reset GPIOA 0x100)
;    *
;    * USART3 (GPS) @ 0x08013B20:
;    *   Base address: 0x40004800
;    *   BRR = 6250 (9600 baud from 60 MHz APB1)
;    *   PB10 = TX (AF_PP), PB11 = RX (IPU)
;    *   OEM uses polled I/O (ISR vectors alias to CRC-16 @ 0x08024E52)
;    *
;    * Mode conflict - usart3_audio_init @ 0x08013FCC:
;    *   if (g_config[1] == 1): CLR PA8 (GPS off), init USART3 for audio
;    *   GPS and serial audio are mutually exclusive on USART3
;    *
;    * NMEA parsing is our addition - OEM has minimal GPS handling. */
;
; --- 17. SI4732 broadcast receiver - I2C + power-up/tune -------------------
;
;   /* SI4732 bit-bang I2C on PB6 (SCL) / PB7 (SDA), address 0x11.
;    * Reset via PA6 (FM_RESET), active-low.
;    *
;    * OEM I2C functions (V0.27):
;    *   i2c_start_send_address @ 0x08025A7C
;    *   i2c_stop               @ 0x08025B5C
;    *   i2c_write_byte         @ 0x08025BC0
;    *   i2c_read_byte          @ 0x080259B4
;    *   i2c_send_cmd           @ 0x08026584
;    *   i2c_read_resp          @ 0x080264F0
;    *   wait_cts               @ 0x0802662C (poll status bit 7, 100 retries)
;    *   set_property           @ 0x08026604 [0x12, 0x00, prop_hi, lo, val_hi, lo]
;    *
;    * Power-up commands (@ 0x08026460):
;    *   FM:  [0x01, 0x10, 0x05]  (FUNC_FM  | PATCH, analog out)
;    *   AM:  [0x01, 0x11, 0x05]  (FUNC_AM  | PATCH, analog out)
;    *   SSB: [0x01, 0x31, 0x05]  (FUNC_AM  | PATCH | XOSCEN, analog out)
;    *   WB:  [0x01, 0x13, 0x05]  (FUNC_WB  | PATCH, analog out)
;    *
;    * Power-down (@ 0x0800E94C): [0x11], read 1 byte, delay(600)
;    *
;    * SSB patch (@ 0x080265D0): 15,832 bytes from flash 0x08028BA0
;    *   uploaded as 1,979 × 8-byte I2C blocks with wait_cts between each.
;    *   Patch is proprietary - SSB mode non-functional without it.
;    *
;    * NOAA WB frequencies use uint32_t (162400-162550 kHz > uint16_t max).
;    * OEM AM tune (@ 0x08003C34): [0x40, flags, freq_hi, freq_lo, 0, 1] */
;
; --- 18. Menu system + display render engine ----------------------------
;
;   /* settings_menu_engine @ 0x08011AC4 (17,740 bytes):
;    *   Command-dispatch state machine. CMP chain on r1:
;    *     r1==0x02: init/setup
;    *     r1==0x03: navigation
;    *     r1==0x05: scroll
;    *     r1==0x07: edit value
;    *     r1==0x10: exit/back
;    *     r1==0x11: focus change
;    *     r1==0x12: menu enter (→ display_menu_screen if g_state[29]!=0)
;    *     r1==0x13: back to category list
;    *     r1==0x14: open/enter menu (sets g_state @ 0x20000215 = 1)
;    *     r1==0x15: sub-item select
;    *     r1==0x16: value commit
;    *     r1==0x17: edit mode enter
;    *     r1==0x18: scroll with text backspace
;    *     r1==0x1C: reset handler
;    *     r1==0x1F: special mode
;    *     r1==0x24: extended op 1
;    *     r1==0x25: extended op 2
;    *     r1>=0xA0: channel/zone select mode
;    *
;    *   Key refs:
;    *     g_config        @ 0x2000A340
;    *     display_state   @ 0x20000215
;    *     g_display       @ 0x2000A8D0 (173 bytes)
;    *
;    *   Sub-functions:
;    *     display_menu_screen   @ 0x08010790
;    *     menu_list_renderer    @ 0x080108F4
;    *     menu_item_draw        @ 0x08010BC8
;    *     menu_settings_draw    @ 0x08010AD8
;    *     menu_scroll_handler   @ 0x080102DC
;    *     menu_handler_display  @ 0x0801145C (296B)
;    *     menu_handler_audio    @ 0x08011598 (272B)
;    *     menu_handler_timer    @ 0x080116B8 (316B)
;    *     menu_handler_scan     @ 0x08011808 (300B)
;    *
;    *   String table @ 0x0805A440-0x0805BC00 (7 KB):
;    *     Format: 02 ID 20 "string" 00  (item)
;    *             07 20 "string" 00     (header)
;    *     Top-level: 0x0805B3D0 (12 categories, IDs 0x12-0x1D)
;    *     ASCII + GB2312 (Chinese) dual encoding
;    *
;    * display_render_engine @ 0x08019344 (27,380 bytes):
;    *   TBB jump table indexed by g_rf_state[3] @ 0x2000A3B7:
;    *     Mode 0: VFO main display
;    *     Mode 1: → 0x0801FB50 (status/alternate view)
;    *     Mode 2: → 0x0801FB50 (second alternate)
;    *     Mode 3: → 0x080174D4 (frequency display mode)
;    *     Mode 4: → 0x08017530 (channel info display)
;    *     Mode 5: → 0x080174D4 (same as mode 3)
;    *     Mode 6: → 0x0800B65C (special, arg=1)
;    *     Mode 7: → 0x0801FDA4 (extended display)
;    *     Mode ≥11: NOP (pop {r4, pc})
;    *
;    *   Sub-renderers:
;    *     screen_draw_main       @ 0x08017710 (VFO/channel main)
;    *     screen_draw_freq       @ 0x080173F4 (large freq digits)
;    *     screen_draw_line_a     @ 0x08017084 (VFO A info line)
;    *     screen_draw_line_b     @ 0x08017174 (VFO B info line)
;    *     screen_draw_status_line @ 0x08017AC8 (footer)
;    *     display_status_bar     @ 0x08020340 (procedural icons)
;    *
;    *   All icons: procedural (text + rectangles, no bitmap assets).
;    *   Battery: 28x12 rect with 4 inner bars (5x8 each).
;    *   S-meter: 12-segment bar graph (S1-S9 + 3 dB-over). */
;

; --- 19. Scanner, VOX, DTMF, Spectrum -----------------------------------
;
;   /* Scanner main handler @ 0x08009B88 (292B):
;    *   Polling-based state machine called from main loop.
;    *   VFO mode: steps frequency within band, wraps at both edges.
;    *   Memory mode: iterates scannable channels, wraps to ch 0.
;    *   Squelch check: debounced (3 consecutive reads to avoid noise).
;    *   Resume modes: carrier-detect, timed, manual stop.
;    *   OEM uses frequency-dependent squelch calibration (@ 0x200000E4)
;    *   with ~12 index positions per VHF/UHF band - our code uses
;    *   static 9-level table (acceptable for initial implementation).
;    *
;    * VOX detection (BK4829 hardware):
;    *   REG 0x31 bit 1 = VOX enable
;    *   REG 0x71 = threshold (9-level table from OEM @ 0x0802B7FC)
;    *   REG 0x0C bit 4 = VOX triggered status
;    *   REG 0x30 = RX/TX path: 0xBFF1 (RX), 0xC3FA (TX)
;    *   Hang timer: ~1000ms after audio stops before returning to RX.
;    *   Anti-VOX: suppressed when speaker output active.
;    *   PTT conflict guard: VOX won't initiate TX if manual PTT active.
;    *
;    * DTMF detection (bk4829_check_dtmf_active @ 0x0801B2B0, 34B):
;    *   REG 0x0D (NOT 0x0C) - bit 15 = DTMF detect (active LOW)
;    *     movs r0, #13  @ 0x0801B2B4
;    *     lsls r1, r0, #16; bpl → bit15 set = NO dtmf (return 0)
;    *   When detected: ubfx r0, r0, #0, #11 → tone status [10:0]
;    *   REG 0x0E - extended data / decoded digit
;    *     movs r0, #14  @ 0x0801B2CA
;    *   Return: (0x0D[10:0] << 16) | 0x0E[15:0]
;    *
;    * DTMF tone generation:
;    *   REG 0x70 used for AFSK in APRS (0x00AC TX, 0x00EC RX).
;    *   BK4829 DTMF coefficient registers 0x78-0x7E not found in OEM.
;    *   Tone generation mechanism needs BK4829 datasheet verification.
;    *
;    * Spectrum analyzer:
;    *   Custom feature - no direct OEM equivalent found.
;    *   Uses BK4829 freq set (0x0801BD40) + RSSI read (REG_0C, 0x0801BEC4)
;    *   240 bins across configurable span, 3 color-coded RSSI levels.
;    *
;    * Cross-band repeat:
;    *   Dual BK4829: CHIP0=VFO-B (UHF), CHIP1=VFO-A (VHF).
;    *   RX squelch on one chip → radio_ptt_on() on other.
;    *   TOT: 180s max relay. Hang: 2s after carrier drop.
;    *   Audio routing via relay_select(sub, 2) mode in radio_ptt_on(). */
;
; --- 20. Bluetooth and CPS programming ---------------------------------
;
;   /* Bluetooth USART1 init @ 0x080074EC (138B):
;    *   PA9=TX (AF_PP, 2MHz), PA10=RX (IPU)
;    *   Baud 115200 (BRR=521 @ 60MHz APB2), 8N1, RX+TX enable
;    *   HC-05/BT-04 SPP module (classic Bluetooth, NOT BLE)
;    *   OEM uses polled I/O (all UART ISRs route to CRC-16 @ 0x08024E52)
;    *   Zero "AT+" strings in OEM binary - no AT command mode used.
;    *   PE9 (SW_TO_BT): Bluetooth audio/power switch (low confidence).
;    *   OEM RX buffer: 512 bytes @ 0x2000AF70
;    *
;    * CPS programming_handler @ 0x08006A68 (16,500B):
;    *   UART4 init @ 0x08022762: 115200 baud, PC10=TX, PC11=RX
;    *   CPS mode flag: RAM 0x2000A3B4 + 0x4A, value 0xA5 = active
;    *   Model string @ 0x080003E0: "RT-950      " (12 chars)
;    *   Handshake: 5+ arbitrary bytes → mute RF, send model ID
;    *   Frame: [0xA5][0xFF][0xFF][0xFF][Cmd][Len][Data...][CRC_H][CRC_L]
;    *   Commands: 0x52=Read, 0x57=Write, 0x45=Erase, 0x54/0x58=End
;    *   Address: 3 bytes (24-bit, full 2MB W25Q16 flash range)
;    *   RF mute: BK4829 REG 0x51 = 0x0300 on enter, 0x0000 on exit.
;    *
;    * CRC polynomial in OEM @ 0x08024E52: 0x8408 (reflected CRC-CCITT,
;    * init 0xFFFF). This may be for APRS AX.25 FCS, not CPS framing.
;    * CPS CRC variant needs verification against PC CPS software. */
;
; --- 21. APRS (MIC-E encoding, FSK TX/RX, AX.25 FCS) -----------------
;
;   /* APRS TX path - OEM flow verified against disassembly:
;    *
;    *   FSK register setup (bk4829_fsk_tx_init equivalent):
;    *     REG 0x58 = 0x00C9   @ 0x0801EB8C  (FSK TX mode, 4800 baud)
;    *     REG 0x72 = 0x60CA   @ 0x0801EB94  (1200/2200 Hz AFSK tones)
;    *     REG 0x70 = 0x00AC   @ 0x0801EB9C  (AFSK modulation enable)
;    *     REG 0x30 += 0x0200  @ 0x0801EBA4  (enable FSK engine)
;    *
;    *   FSK header (sync word) from OEM ROM @ 0x0802C260:
;    *     {0xFB, 0x72, 0x40, 0x99, 0xA7, 0x00, 0x00, 0x00}
;    *     => REG 0x5A = 0xFB72, REG 0x5B = 0x4099
;    *
;    *   FSK FIFO data TX @ 0x0801EEF4:
;    *     REG 0x3F = 0x8000  (FIFO reset)
;    *     REG 0x59 = 0x8028  (sync + TX enable)
;    *     REG 0x59 = 0x0028  (clear sync request)
;    *     Load REG 0x5F with data words (7-word = 14-byte FIFO)
;    *     REG 0x5C = 0xA700 | byte_count  (length config + trigger)
;    *     REG 0x59 = 0x0828  (start data phase)
;    *     Poll REG 0x0C bit 0 for completion
;    *
;    *   NOTE: BK4829 has 14-byte FIFO. AX.25 MIC-E packets are 30-50+ bytes.
;    *   Multi-load required: fill 14 bytes, wait for drain (~6.7ms/byte at
;    *   1200 baud AFSK), refill. Our implementation streams in chunks.
;    *
;    *   AX.25 FCS: CRC-16 CCITT poly 0x8408 (reflected), init 0xFFFF,
;    *   final XOR 0xFFFF. 2 bytes appended little-endian after info field.
;    *   OEM CRC @ 0x08024E52 uses same polynomial.
;    *
;    *   MIC-E destination encoding @ 0x0800AC2C:
;    *     Bytes 0-5 of dest addr encode lat digits + N/S/lon100/W/E flags.
;    *     Digits 0-9 → ASCII '0'-'9' (custom=0) or 'P'-'Y' (custom=1)
;    *     Byte 3: >=0x50 = North; Byte 4: >=0x50 = lon+100; Byte 5: >=0x50 = West
;    *
;    *   AX.25 frame builder @ 0x0800C97C:
;    *     [Dest(7)][Src(7)][Digi(7)×n][Ctrl=0x03][PID=0xF0][Info...][FCS(2)]
;    *     SSID byte 6 of last address has bit 0 set (end-of-address marker)
;    *
;    *   OEM PTT for APRS: asserts relays + PA before FSK programming.
;    *   Our code calls radio_ptt_on() before bk_fsk_tx_init(). */
;
; --- 22. TX Path - PTT relay sequencing, power control, CTCSS/DCS TX --
;
;   /* PTT TX-ON sequence - OEM @ 0x0801A5D0:
;    *   1. relay_select(sub, 0) - assert all 6 relay GPIOs LOW (active-low)
;    *      PE13 (PTT_PRIMARY), PE7 (PTT_MIC), PB1 (PTT_ACC1),
;    *      PE12 (PTT_EXTERNAL), PB0 (PTT_ACC0), PE14 (PTT_PA_GATE)
;    *      OEM relay_select @ 0x0801D268 (378 bytes), mode 0 @ 0x0801D290
;    *   2. bk4829_set_mode(TX):
;    *      REG_30 = 0x0200 (VCO cal only), delay ~39µs (1550 ARM loops)
;    *      REG_30 = 0xC1FE (TX final: PA+MIC_ADC+TX_DSP+PLL+IF+XTAL)
;    *      REG_47 = 0x6658 (AGC LUT[2] for TX)
;    *      REG_48 = 0xB00F | (cal_value << 4) (RF gain, cal from flash)
;    *   3. relay_select(sub, 2) - audio path routing for band
;    *   4. rf_frontend_enable() - PB8+PE4 HIGH (PA power rail)
;    *      CRITICAL: PA enable MUST be LAST, after relays settled.
;    *      5ms relay settling delay added between step 1 and 2.
;    *
;    * PTT TX-OFF sequence - OEM @ 0x0801C308:
;    *   1. relay_select(sub, 1) - RX band/path config
;    *   2. REG_37 = 0x9D1F (disable sub-audio, both chips)
;    *   3. REG_30 = 0xBFF1 (RX enable: RX_EN+PLL+IF+XTAL+BANDGAP)
;    *   NOTE: rf_frontend_disable() NOT called - PE4/PB8 stay high for RX.
;    *
;    * TX power control - REG_36:
;    *   OEM table @ 0x0802B724: Low=0x8E79, Mid=0xA498, High=0xF016
;    *   bk4829_set_tx_power() @ 0x0801BEA4 - direct write before TX enable.
;    *   Power set BEFORE REG_30 TX activation - correct sequencing.
;    *
;    * CTCSS TX encoding - BK4829 hardware tone generator:
;    *   REG_51 = 0x904A (CTCSS mode, gain=74)
;    *   REG_07 = (tone_Hz_x10 * 206489) / 100000 [13-bit freq word]
;    *   REG_37 = 0x9F1F (enable sub-audio processing, bit 15)
;    *   Programmed BEFORE PTT in vfo_apply_state(), not during PTT-on.
;    *
;    * DCS TX encoding - Golay(23,12) codeword:
;    *   REG_51 = 0xA033 (CDCSS mode, gain=51; | 0x4000 for inverted)
;    *   REG_07 = 2775 (fixed DCS bit clock)
;    *   REG_08 = code[11:0], then 0x8000 | code[22:12] (two writes)
;    *   REG_37 = 0x9F1F (sub-audio enable)
;    *
;    * STE (Squelch Tail Elimination):
;    *   134.4 Hz tone via CTCSS path before carrier drop.
;    *   Freq word: (1344 * 206489) / 100000 = 2775
;    *   55ms duration before bk4829_disable_ctcss().
;    *
;    * Roger beep: configurable 1.0/1.45/1.75/2.1 kHz, 200ms via REG_51/07.
;    *
;    * TOT (Transmit Timeout Timer):
;    *   Table: 0/30/60/90/120/150/180/210/240 seconds (index 0 = disabled)
;    *   10-second warning zone, hard cutoff calls radio_ptt_off().
;    *
;    * Band validation: calibration_tx_allowed() checks 4 sub-bands from
;    *   flash @ 0xF000. Refuses TX outside calibrated edges. */
;

; ═══════════════════════════════════════════════════════════════════════════════
; HARDWARE INTERFACE REGISTER REFERENCE (extracted from OEM firmware)
; ═══════════════════════════════════════════════════════════════════════════════
;
; -- BK4829 FREQUENCY PROGRAMMING --------------------------------------------
;
;   bk4829_spi_data_table @ 0x0801BA4C - main frequency-to-register calc
;
;   PLL FORMULA:
;     N_pll = frequency_Hz / 100,000   (divisor = 0x000186A0)
;     UDIV at 0x0801BA60, result stored as 16-bit at [r7+2]
;     Final value written to REG 0x78 (120) via SPI dispatch
;
;   BAND DETECTION (6 bands based on frequency):
;     Band 0: freq < 40 MHz       -> N offset -800, step 10
;     Band 1: 40M  - 50M          -> N offset -700, step 5
;     Band 2: 50M  - 320M         -> N offset -130, step 5 (VHF/UHF primary)
;     Band 3: 320M - 400M(?)      -> N offset -200, step 5
;     Band 4: 400M - 850M(?)      -> N offset -15,  step 5
;     Band 5: > 850M              -> direct lookup
;
;   EXAMPLE: 145.100 MHz -> N=1451, Band 2, adj=1451-130=1321, idx=1321/5=264
;   AGC/filter value looked up from table at 0x200000E4+0x3A[idx]
;   Combined into 16-bit value -> SPI write REG 0x78
;
;   REGISTER WRITES IN FREQUENCY CHAIN:
;     REG 0x78 (120): PLL/VCO multiplication factor N (primary)
;     REG 0x51 (81):  GPIO/TX/RX control (0x0300 for TX mode)
;     REG 0x38/0x39 (56/57): Legacy freq write (direct strb, not SPI)
;
;   VCO SETTLING: ~1.4 seconds total
;     Phase 1: VCO lock wait (bk4829_delay_wait, 1-10ms)
;     Phase 2: IF filter tuning (17 iterations × 80ms = ~1.3s)
;     Phase 3: AGC/receiver batch config (100-200ms)
;
;   CALL CHAIN:
;     bk4829_power_table(0x0801A400)
;       -> bk4829_spi_data_table(0x0801BA4C)  [freq->REG 0x78]
;         -> bk4829_reg_load(0x0801A5A2)      [audio+VCO lock]
;           -> bk4829_filter_setup(0x0800D3EC) [IF filter 17-step]
;             -> bk4829_batch_config(0x0800D24C) [AGC final tune]
;
; -- BK4829 SQUELCH & CTCSS/DCS REGISTERS -------------------------------------
;
;   FROM bk4829_hal_init @ 0x08007144 (init table extraction):
;
;   SQUELCH THRESHOLDS:
;     REG 77 (0x4D) = 0xA004  - RSSI squelch threshold
;     REG 78 (0x4E) = 0x3815  - Noise squelch threshold
;     REG 79 (0x4F) = 0x3F3B  - Combined/glitch threshold
;     REG 47 (0x2F) = 0x9890  - Squelch mode / RX AGC control
;
;   CTCSS/CDCSS:
;     REG 55 (0x37) = 0x9D1F  - CTCSS frequency control (init default)
;     bk4829_audio_config_read(0x0801A0D0): writes REG 55 = 0x9D1F
;     bk4829_reg_table_a(0x0801A09E): writes REG 48=0 + REG 55=0x3A00
;
;   SQUELCH CHECK: rf_squelch_check(0x0800EC2C)
;     Reads g_rf_state[67], sends squelch status via UART (cmd 66='B'/34='"')
;     Extracts RSSI bytes from response at offsets +7[4] and +7[5]
;
; -- BK4829 TX POWER CONTROL & PTT SEQUENCE -----------------------------------
;
;   POWER REGISTERS (fixed at init, bk4829_hal_init):
;     REG 40 (0x28) = 0x0B40  - TX power bias (low)
;     REG 41 (0x29) = 0xAA00  - TX power bias (mid)
;     REG 42 (0x2A) = 0xCC00  - TX power bias (high)
;
;   DYNAMIC POWER: bk4829_set_tx_power @ 0x0801BEA4
;     Writes REG 113 (0x71) - fine TX power scaling
;     Formula: output = (input × 4097 × 63 × 4) / 10000 ≈ input × 103.26
;     Uses SPI dispatch via [0x20000C28 + 8]
;
;   POWER DISPATCH CHAIN:
;     bk4829_power_table(0x0801A400)
;       -> reads g_rf_state[1] (power level) and g_rf_state[269] (power index)
;       -> checks config[56] calibration validity
;       -> rf_power_dispatch(0x0801A4D8)
;           dispatch(0) -> r0=7 (reduced power)
;           dispatch(1) -> r0=6 (normal power)
;       -> power setter at 0x08006928
;       -> rf_relay_switch(band, 0) to set frontend
;
;   PTT-ON SEQUENCE (safe order - PA last):
;     1. rf_relay_switch(band, 2)      - set TX relays/amps
;     2. spk_mute_on_ptt()             - mute speaker, enable mic
;     3. BK4829 TX mode (REG 51=0x0300) - configure RF chip for TX
;     4. rf_power_dispatch()            - set power level
;     5. bk4829_set_tx_power()          - REG 113 fine tune
;     6. SET PE4 (PA_ENABLE HIGH)       - * RF transmission begins
;
;   PTT-OFF SEQUENCE (safe order - PA first):
;     1. CLR PE4 (PA_ENABLE LOW)        - * RF transmission stops
;     2. BK4829 RX mode via bk4829_reg_table_a (REG 48=0, REG 55=0x3A00)
;     3. spk_unmute()                   - enable speaker, disable mic
;     4. rf_relay_switch(band, 1)       - set RX relays
;
;   SAFETY: PE4 is set LAST on TX, cleared FIRST on RX transition
;   This prevents PA damage from impedance mismatch during relay switching
;
; -- RF RELAY & BAND SWITCHING -------------------------------------------------
;
;   rf_relay_switch @ 0x0801A268 (378 bytes)
;   Args: r0=band_mode (0-4+), r1=relay_mode (0-3)
;   Regs: r5=GPIOE(0x40011800), r6=GPIOB(0x40010C00)
;         r7=0x1000(PE12), r8=0x2000(PE13), r9=0x4000(PE14)
;
;   GPIO function mapping:
;     gpio_bits_set(0x080125B2):   STR r1,[r0,#16] -> GPIO_SCR (pin HIGH)
;     gpio_bits_reset(0x080125AE): STR r1,[r0,#20] -> GPIO_CLR (pin LOW)
;
;   MODE 0 (r1=0) - SHUTDOWN / ALL OFF:
;     CLR PE13(U6R_EN), CLR PE7(U3T_EN), CLR PB1(V3T_EN)
;     CLR PE12(U3R_EN), CLR PB0(V3R_EN), CLR PE14(SW3T_EN)
;     -> All RF frontend pins driven LOW
;
;   MODE 1 (r1=1) - RX ACTIVE (band-dependent):
;     Checks g_rf_state[74] == 0xA5 (magic/valid flag)
;     r0=0 (VHF default): CLR PE13, CLR PE12, SET PB0(V3R_EN)
;     r0=1 or 3 (UHF?):  CLR PE13, CLR PB0,  SET PE12(U3R_EN)
;     r0=4 (alt band):    CLR PE12, CLR PB0,  SET PE13(U6R_EN)
;
;   MODE 2 (r1=2) - TX (band-dependent):
;     Checks magic 0xA5, branches on band_mode:
;     VHF path: CLR PB1, SET PE7(U3T_EN), CLR PE14(SW3T_EN)
;     UHF path: CLR PE7, SET PB1(V3T_EN), CLR PE14(SW3T_EN)
;
;   MODE 3 (r1=3) - TX ALT / DISABLE RX:
;     CLR PE13, CLR PE12, CLR PB0 -> disable all RX paths
;
; -- AUDIO ROUTING & SPEAKER CONTROL -------------------------------------------
;
;   spk_mute_on_ptt @ 0x08019254:
;     1. Read GPIOC(0x40011000) bit 15 (PC15) - external PTT signal
;     2. If PC15=LOW: debounce 50ms, re-check
;     3. Still LOW: SET PE1 (SPK_MUTE HIGH -> mute speaker)
;     4. Then: SET PB8 (MIC_EN -> enable mic path)
;     ∴ PE1: HIGH = speaker muted, LOW = speaker active
;     ∴ PB8: HIGH = mic enabled (set during PTT)
;
;   spk_unmute @ 0x0801929C:
;     Complex state machine using g_rf_state(0x2000A3B4)
;     State toggle at offset [34], delay counter at offset [36]
;     State 0->1: rf_relay_switch(band, 0) [idle] + lcd_cmd_dispatch(0)
;     State 1->0: rf_relay_switch(band, 1) [RX] + audio_bk4829_config(0)
;     Loads band from g_rf_flags(0x2000A41C)[266]
;
;   audio_state_machine @ 0x08006574:
;     4 states at g_audio_state(0x2000A994)[14]:
;     State 0: idle - if g_rf[75]=0, CLR PB9(GPIOB 0x200)
;     State 1: waiting - return immediately
;     State 2: setup - audio_route_setup() + SET PB9(GPIOB 0x200)
;     State 3: beep - beep_play() -> state 4
;     PB9 toggle: audio amp enable (SET=enabled, CLR=disabled)
;
;   beep_play @ 0x08003808:
;     Timer config: prescaler=3, ARR=0x030D(781), clkdiv=32
;     Beep freq = 120MHz / (3+1) / (781+1) ≈ 38.4 kHz timer rate
;     Fills audio buffer from g_audio_buf(0x2000DF34)
;     Volume: derived from g_settings(0x2000ADD0)[30] mod 9 + 2
;
; -- EEPROM DATA STRUCTURES ----------------------------------------------------
;
;   XOR OBFUSCATION KEY: {0x41, 0x41, 0x41, 0x41} = "AAAA"
;     Location: RAM 0x20000220 (loaded from flash init data at 0x0805C53E)
;     All 4 bytes identical -> effectively XOR with 0x41 per byte
;
;   eeprom_block_copy @ 0x0801F8D0 - selective XOR decode:
;     For each byte: key_byte = xor_key[i % 4]
;     SKIP XOR if: key_byte==0x20, src==0x00, src==0xFF,
;                  src==key_byte, src==(key_byte^0xFF)
;     Otherwise: dest = src ^ key_byte
;
;   CRC16: crc16_update @ 0x0800A4B8
;     Polynomial: 0x1021 (CRC-CCITT)
;     Initial value: 0x0000 (XModem variant)
;     Standard bit-by-bit shift-and-XOR, 8 bits per byte
;
;   FLASH LAYOUT (W25Q16, addresses in SPI flash space):
;     0x0000-0x7FFF: Channel data (100 slots)
;     0x8000-0x8FFF: Settings A (41 slots × 98B, wear-leveled)
;     0x9000-0x9FFF: Settings B (41 slots × 96B, wear-leveled)
;     0xB000-0xBFFF: Extended settings (25 slots × 160B)
;     0xF000-0xFFFF: Calibration data
;
; -- SI4732 FIRMWARE PATCH -----------------------------------------------------
;
;   Patch location: Flash 0x08028BA0 (binary offset 0x28BA0)
;   Format: Silicon Labs proprietary - uint16_t index table + patch segments
;   Size: ~58KB total (highest offset 0xE28E)
;   Property IDs: 01, 02, 03, 04, 06, 08 (standard SI47xx property set)
;
;   Communication: I2C bit-bang on PB6(SCL) + PB7(SDA), address 0x11
;   Reset: PA6 (FM_RESET) - toggle to reset SI4732 before patch upload
;   Additional: PE10(SCLK) + PE11(MOSI) for SPI bit-bang control path
;
;   Patch upload triggered by bt_flash_comms command 0x13 ("FM Init")
;   The CPS/BT protocol handler integrates SI4732 control
;
; -- BLUETOOTH MODULE PROTOCOL -------------------------------------------------
;
;   Module: PROPRIETARY Radtel OEM (NOT HC-05/HC-06/BK3266/CSR)
;   Evidence: ZERO "AT+" strings in entire binary, no commercial BT identifiers
;   USART1: PA9(TX)/PA10(RX) @ 115200 baud, 8N1
;
;   PROTOCOL: Binary command dispatch (NOT ASCII AT commands)
;   Packet size: up to 512 bytes, RX buffer at 0x20010A7C
;
;   bt_flash_comms @ 0x080206C8 - command dispatcher (370+ bytes):
;     Cmd 0x02: Flash/BT data read
;     Cmd 0x10: BT state sync
;     Cmd 0x11: State transition
;     Cmd 0x12: Delay (50ms)
;     Cmd 0x13: FM initialization (SI4732 control)
;     Cmd 0x16: ROM data read
;     Cmd 0x17: Register write
;     Cmd 0x18: Flash write
;     Cmd 0x19-0x30: Additional commands (48+ total IDs)
;
;   bt_protocol_handler @ 0x080222C8:
;     Receives from 512B RX buffer -> memcpy -> bt_state_sync(0x080195E8)
;
;   Power control: No separate BT power pin found - likely always-on
;   Audio routing: BT uses UART only, no PE9 audio switch confirmed
;
; -- DMA CHANNEL MAP & INTERRUPT PRIORITIES ------------------------------------
;
;   DMA CHANNEL ALLOCATION:
;     DMA1_CH1 (0x40020008): ADC1 -> buffer at 0x2000BBEC (128 transfers)
;     DMA2_CH1 (0x40020408): LCD pixel push -> GPIOD_ODR, PL=HIGH
;     DMA2_CH3 (0x40020430): DAC audio -> DAC1_DHR12R1, PL=MED, circular
;     Both LCD+Audio triggered by TIM6 TRGO
;     Master init: tim6_dac_dma_init(0x08018EC0)
;
;   NVIC CONFIGURATION:
;     AIRCR = 0x05FA0004 -> 2-bit preemption, 2-bit subpriority
;     OEM uses POLLED I/O - no timer or UART interrupts enabled
;     Our firmware adds: TIM2(pri 3), TIM3(pri 4), USART1/3(pri 5), UART4(pri 6)
;     SysTick at 1ms (implicit highest priority)
;
;   KEY ISRs IN OEM: nvic_irq_config(0x08022602) - loop-based enable/disable
;     14 ISR handlers identified but most are minimal stubs
;
; -- BOOT TIMING & INIT ORDER --------------------------------------------------
;
;   VTOR: flag_set_init(0x0801886C) writes 0xE000ED08 with mask 0x1FFFFF80
;   IWDG: ZERO references to 0x40003000 - OEM does NOT use watchdog
;   delay_ms(0x08024D7C): counter at 0x2000A2EC, polls dma_buffer_config
;     (keeps audio DMA alive during waits - important pattern)
;   delay_short(0x0800A962): CPU loop, r0=r0×31 then countdown (~258ns/unit)
;   No explicit delays between init steps - each init handles own settling
;
; -- COMPLETE BK4829 INIT REGISTER TABLE --------------------------------------
;
;   bk4829_hal_init @ 0x08007144 - 43 register writes via dispatch [r4+8]
;   Dispatch table: r4 = 0x20000C28, write = [r4+8], read = [r4+4]
;
;   Phase 1 - Reset:
;     REG  0 (0x00) = 0x8000  then  0x0000    ; Chip reset + clear
;
;   Phase 2 - Core configuration:
;     REG 55 (0x37) = 0x9D1F                   ; CTCSS/CDCSS control
;     REG 19 (0x13) = 0x03DF                   ; RX comparator threshold
;     REG 18 (0x12) = 0x03DB                   ; Comparator control
;     REG 17 (0x11) = 0x033A                   ; AGC table index
;     REG 16 (0x10) = 0x0318                   ; AGC config
;     REG 20 (0x14) = 0x0210                   ; AGC gain
;     REG 73 (0x49) = 0x2AB2                   ; RF gain config
;     REG 123(0x7B) = 0x73DC                   ; Internal calibration
;     REG 28 (0x1C) = 0x0F80                   ; AF gain DAC
;     REG 29 (0x1D) = 0xE555                   ; RSSI compensation
;     REG 30 (0x1E) = 0x4C58                   ; IF filter bandwidth
;     REG 31 (0x1F) = 0x865A                   ; IF frequency
;     REG 62 (0x3E) = 0x94C6                   ; Band select / VCO
;     REG 63 (0x3F) = 0x07FE                   ; Band control
;     REG 37 (0x25) = 0xC1BA                   ; TX audio path
;     REG 58 (0x3A) = 0x9A7C                   ; Modulation config
;     REG 25 (0x19) = 0x1041                   ; Deviation setting
;     REG 40 (0x28) = 0x0B40                   ; TX power (low)
;     REG 41 (0x29) = 0xAA00                   ; TX power (mid)
;     REG 42 (0x2A) = 0xCC00                   ; TX power (high)
;     REG 44 (0x2C) = 0x0022                   ; TX control
;     REG 47 (0x2F) = 0x9890                   ; Squelch mode / RX AGC
;     REG 83 (0x53) = 0x2028                   ; Internal config
;     REG 126(0x7E) = 0x303E                   ; Calibration
;     REG 70 (0x46) = 0x6050                   ; Audio filter
;     REG 74 (0x4A) = 0x5430                   ; AGC table
;     REG 72 (0x48) = 0xB3BF                   ; AGC config
;     REG 73 (0x49) = 0x2AB2                   ; RF gain (2nd write)
;     REG 74 (0x4A) = 0x5430                   ; AGC table (2nd write)
;     REG 77 (0x4D) = 0xA004                   ; * RSSI squelch threshold
;     REG 78 (0x4E) = 0x3815                   ; * Noise squelch threshold
;     REG 79 (0x4F) = 0x3F3B                   ; * Combined threshold
;     REG 119(0x77) = 0xCCEF                   ; Internal
;     REG 126(0x7E) = 0x303E                   ; Calibration (2nd)
;
;   Phase 3 - Read-modify-write:
;     REG 64 (0x40): READ -> mask top 4 bits -> OR 0x04D2 -> WRITE
;
;   Phase 4 - Final config:
;     REG 125(0x7D) = 0xE912                   ; Calibration
;     REG 72 (0x48) = 0xB3FF                   ; AGC config (updated)
;     REG 116(0x74) = 0xDF22                   ; Internal
;     REG 68 (0x44) = 0x91C1                   ; Dual-tone detector A
;     REG 69 (0x45) = 0x3040                   ; Dual-tone detector B
;     REG 117(0x75) = 0xE61C                   ; Internal
;     REG 84 (0x54) = 0x91C1                   ; Dual-tone detector A2
;     REG 85 (0x55) = 0x3040                   ; Dual-tone detector B2
;     Tail call to 0x0801BC2C with r0=0
